// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, 5 ether);
        vm.deal(bob, 10 ether);

        vm.prank(alice);
        c.addToBalance{value: 5 ether}();

        vm.prank(bob);
        c.addToBalance{value: 10 ether}();

        vm.prank(bob);
        c.withdrawBalance();

        uint256 bobBalance = c.getBalance(bob);
        assertTrue(bobBalance == 0);
    }
}
